H.background();
const w = H.W, hh = H.H;
const n = Math.max(1, Math.round(P.n));
const r = Math.max(1, Math.min(Math.round(P.r), n));
const isComb = P.kind >= 0.5;
function fact(x) { let p = 1; for (let i = 2; i <= x; i++) p *= i; return p; }
const nPr = fact(n) / fact(n - r);
const nCr = nPr / fact(r);
H.text(isComb ? "Combinations: C(n,r) = n! / (r!·(n−r)!)" : "Permutations: P(n,r) = n! / (n−r)!", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("n = " + n + "   r = " + r + (isComb ? "   order does NOT matter" : "   order matters"), 24, 52, { color: H.colors.sub, size: 13 });
const slotW = 54, slotH = 54, gap = 14;
const totalW = r * slotW + (r - 1) * gap;
const sx = Math.max(40, (w - totalW) / 2), sy = 110;
const step = Math.floor((t * 0.9) % (r + 1));
for (let i = 0; i < r; i++) {
  const x = sx + i * (slotW + gap);
  const choices = n - i;
  const filled = i < step;
  H.rect(x, sy, slotW, slotH, { fill: filled ? H.colors.accent : H.colors.panel, stroke: i === step ? H.colors.warn : H.colors.axis, width: i === step ? 3 : 1.5, radius: 8 });
  H.text(String(choices), x + slotW * 0.5, sy + slotH * 0.5 + 8, { color: filled ? H.colors.bg : H.colors.ink, size: 22, weight: 700, align: "center" });
  H.text("slot " + (i + 1), x + slotW * 0.5, sy - 10, { color: H.colors.sub, size: 11, align: "center" });
  if (i < r - 1) H.text("×", x + slotW + gap * 0.5, sy + slotH * 0.5 + 7, { color: H.colors.ink, size: 20, weight: 700, align: "center" });
}
H.text("Each slot: one FEWER choice than the last (no repeats).", sx, sy + slotH + 30, { color: H.colors.sub, size: 12 });
H.text("P(n,r) = " + nPr + "   ordered lineups", sx, sy + slotH + 58, { color: H.colors.accent, size: 15, weight: 600 });
if (isComb) {
  H.text("÷ r! = ÷" + fact(r) + " (drop the " + fact(r) + " orderings of the SAME r picks)", sx, sy + slotH + 84, { color: H.colors.violet, size: 13 });
  H.text("C(n,r) = " + nCr + "   unordered groups", sx, sy + slotH + 110, { color: H.colors.good, size: 16, weight: 700 });
}
H.legend([{ label: "filled slot", color: H.colors.accent }, { label: "current", color: H.colors.warn }], w - 170, 28);
